  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    diagnostics = []
    for call in calls:
        cid = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        gain = loss_without - loss_with
        pt = call['prediction_tokens']
        if pt > 0:
            normalized_gain = gain / pt
        else:
            normalized_gain = 0.0
        accepted = call['parseable'] and (normalized_gain >= threshold)
        diagnostics.append({
            'accepted': accepted,
            'call_id': cid,
            'normalized_gain': normalized_gain
        })
    accepted_ids = [d['call_id'] for d in diagnostics if d['accepted']]
    return {'accepted_call_ids': accepted_ids, 'diagnostics': diagnostics}
